import pandas as pd
import numpy as np

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)

# After fixing commas and scientific notation, let's see ranges for all numeric columns
def parse_val(v):
    if pd.isna(v):
        return np.nan
    v = str(v).replace(',', '.')
    try:
        return float(v)
    except:
        return np.nan

for col in df.columns[1:]:
    vals = df[col].apply(parse_val).dropna()
    print(f'{col}: min={vals.min():.4f}, max={vals.max():.4f}, median={vals.median():.4f}, mean={vals.mean():.4f}')
